float drawCircle(vec2 uv, vec2 center, float radius) {
    return smoothstep(radius, radius - .1, length(uv - center));
}

vec2 getInnerPoint(vec2 id) {
    vec2 point = id ;
    return point +(sin(-iTime*.4)+1.)*.01 ;
}

vec3 drawLayer(vec2 lv, float time, float z) {
    vec3 m = vec3(0.);

    vec2 id = floor(lv);
    vec2 point = getInnerPoint(id);

    m += drawCircle(lv, point, .1*(length(z+length(id*.07))*.8));

    m *= ((normalize(vec3(1.,2., 3.)+id.xyx*vec3(sin(iTime*2.+id.y),cos(time+2.+id.y),sin(iTime+id.x)))-.5)*normalize(length(id)+sin(time+id.yxy-z)))*(length(z*7.)*40.);
    return m;
}

mat2x2 getRotationMatrix(float time) {
    return mat2x2(cos(time), -sin(time*.97), sin(time*1.01), cos(time*.99));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = 8.*(2.*fragCoord-iResolution.xy)/ min(iResolution.x,iResolution.y); 

    vec3 m = vec3(0.);
    float time = iTime * .1;

    float amount_layers = 16.;
    for (float i = 0.; i < amount_layers; i += 1.) {
        float z = fract(2.5 * (i / (amount_layers * 2.)) - time);

        float fade_in = smoothstep(0., .4, z);
        float fade_out = smoothstep(1., .1, z);
        float fade = fade_in * fade_out;

        vec2 lv = getRotationMatrix(z * 4.) * uv * z;
        m += drawLayer(lv, time,z) * fade;
    }


    vec3 col = m;

    fragColor = vec4(pow(col,vec3(1./2.2)), 1.);
}
